after.content:
        notifyUpdate(sessionId, update);
    }
}
private java.util.Optional<AcpV2PreviewModel.StructuredDiff> structuredDiff(AgentEvent.ToolChanged tool) {
    if (tool.status() != AgentEvent.ToolStatus.COMPLETED
            || !List.of("write", "edit").contains(tool.toolName())
            || !(tool.arguments().get("path") instanceof String path)) {
        return java.util.Optional.empty();
    }
    String absolute = java.nio.file.Path.of(sessions.snapshot(sessionId).workingDirectory())
            .resolve(path).toAbsolutePath().normalize().toString();
    var change = new AcpV2PreviewModel.Change(
            "write".equals(tool.toolName())
                    ? AcpV2PreviewModel.Operation.ADD : AcpV2PreviewModel.Operation.MODIFY,
            null, absolute, "text", "text/plain");
    return java.util.Optional.of(new AcpV2PreviewModel.StructuredDiff(
            List.of(change), java.util.Optional.empty()));
}

